import { readFileSync, writeFileSync, readdirSync, statSync } from "node:fs";
import { join } from "node:path";

const OLD = "disableTooltip";
const NEW = "hideHint";
const PILL_TAGS = new Set(["app-pill", "app-fancy-pill", "app-status-pill"]);

function walk(dir, out = []) {
    for (const name of readdirSync(dir)) {
        const p = join(dir, name);
        if (statSync(p).isDirectory()) walk(p, out);
        else out.push(p);
    }
    return out;
}

/** Rename the input on pill start tags and on template-ref reads of pills. Returns the new template text. */
function processTemplate(src) {
    let out = "";
    let i = 0;
    const pillRefs = new Set();
    const tagRe = /<(app-pill|app-fancy-pill|app-status-pill)(?=[\s\/>])/g;
    let m;
    while ((m = tagRe.exec(src)) !== null) {
        const start = m.index;
        // scan to end of start tag, respecting quotes
        let j = start + m[0].length;
        let quote = null;
        while (j < src.length) {
            const c = src[j];
            if (quote) { if (c === quote) quote = null; }
            else if (c === '"' || c === "'") quote = c;
            else if (c === ">") break;
            j++;
        }
        if (j >= src.length) throw new Error("unterminated tag at " + start);
        const tagBody = src.slice(start + m[0].length, j); // attributes section
        // tokenize attributes: name (=value)?
        let nb = "";
        let k = 0;
        while (k < tagBody.length) {
            const c = tagBody[k];
            if (/\s/.test(c) || c === "/") { nb += c; k++; continue; }
            // attribute name
            let nameEnd = k;
            while (nameEnd < tagBody.length && !/[\s=\/]/.test(tagBody[nameEnd])) nameEnd++;
            let name = tagBody.slice(k, nameEnd);
            if (name.startsWith("#")) pillRefs.add(name.slice(1));
            if (name === OLD) name = NEW;
            else if (name === `[${OLD}]`) name = `[${NEW}]`;
            else if (name.includes(OLD)) throw new Error("unexpected attr " + name + " at " + start);
            nb += name;
            k = nameEnd;
            // optional whitespace = whitespace value
            let save = k;
            while (k < tagBody.length && /\s/.test(tagBody[k])) k++;
            if (tagBody[k] === "=") {
                nb += tagBody.slice(save, k + 1);
                k++;
                while (k < tagBody.length && /\s/.test(tagBody[k])) { nb += tagBody[k]; k++; }
                const q = tagBody[k];
                if (q === '"' || q === "'") {
                    const end = tagBody.indexOf(q, k + 1);
                    nb += tagBody.slice(k, end + 1);
                    k = end + 1;
                } else {
                    let e = k;
